// One TCP connection, several HTTP/2 streams, 9-byte frame header per DATA frame.
const FRAME_HEADER = 9; // bytes: length, type, flags, stream ID
const MAX_CONCURRENT_STREAMS = 100;
const CHUNK = 100; // bytes of body per DATA frame

function stream(id, totalBytes) {
  const frames = [];
  for (let sent = 0; sent < totalBytes; sent += CHUNK) {
    frames.push({ id, off: sent, len: Math.min(CHUNK, totalBytes - sent) });
  }
  return frames;
}

// Server interleaves: round-robin across active streams.
function interleave(streams) {
  const queues = streams.map((s) => s.slice());
  const wire = [];
  let active = true;
  while (active) {
    active = false;
    for (const q of queues) {
      if (q.length) { wire.push(q.shift()); active = true; }
    }
  }
  return wire;
}
